	// TODO: what if the new response doesn't have a body by design?
	// see: https://github.com/caddyserver/caddy/pull/6232#issue-2235224400
	if recorder.Size() == 0 && buf.Len() > 0 {
		_, err := io.Copy(w, buf)
		return err
	}
