307			// WriteHeader alone may remain buffered by net/http. Incremental
308			// forwarding requires the header section to be sent downstream now.
309			_ = http.NewResponseController(rw.ResponseWriter).Flush()
310		}
311	}
312	
313	func isSSE(contentType string) bool {
314		if len(contentType) < len(sseMediaType) || !strings.EqualFold(contentType[:len(sseMediaType)], sseMediaType) {
315			return false
316		}
317	
318		// After the media type, allow only optional whitespace followed by the
319		// end of the value or a parameter separator, so a longer type such as
320		// "text/event-streamfoo" or garbage like "text/event-stream nonsense"
321		// does not match. TrimLeft on the tail does not allocate.
322		rest := strings.TrimLeft(contentType[len(sseMediaType):], " \t")
323	
324		return rest == "" || rest[0] == ';'
325	}
326	
327	// Match determines, if encoding should be done based on the ResponseMatcher.
328	func (enc *Encode) Match(rw *responseWriter) bool {
329		return enc.Matcher.Match(rw.statusCode, rw.Header())
330	}
331	
332	// FlushError is an alternative Flush returning an error. It delays the actual Flush of the underlying
333	// ResponseWriterWrapper until headers were written.
334	func (rw *responseWriter) FlushError() error {
335		if !rw.wroteHeader && rw.statusCode == 0 && caddyhttp.IsIncremental(rw.Header()) {
336			rw.WriteHeader(http.StatusOK)
337		}
338	
339		// WriteHeader wasn't called and is a CONNECT request, treat it as a success.
340		// otherwise, wait until header is written.
341		if rw.isConnect && !rw.wroteHeader && rw.statusCode == 0 {
342			rw.WriteHeader(http.StatusOK)
343		}
344	
345		if !rw.wroteHeader {
346			// flushing the underlying ResponseWriter will write header and status code,
347			// but we need to delay that until we can determine if we must encode and
348			// therefore add the Content-Encoding header; this happens in the first call
349			// to rw.Write (see bug in #4314)
350			return nil
351		}
352		// also flushes the encoder, if any
353		// see: https://github.com/jjiang-stripe/caddy-slow-gzip
354		if rw.w != nil {
355			err := rw.w.Flush()
356			if err != nil {
357				return err
358			}
359		}
360		//nolint:bodyclose
361		return http.NewResponseController(rw.ResponseWriter).Flush()
362	}
363	
364	// Write writes to the response. If the response qualifies,
365	// it is encoded using the encoder, which is initialized
366	// if not done so already.
367	func (rw *responseWriter) Write(p []byte) (int, error) {
368		// ignore zero data writes, probably head request
369		if len(p) == 0 {
370			return 0, nil
371		}
372	
373		// WriteHeader wasn't called and is a CONNECT request, treat it as a success.
374		// otherwise, determine if the response should be compressed.
375		if rw.isConnect && !rw.wroteHeader && rw.statusCode == 0 {
376			rw.WriteHeader(http.StatusOK)
377		}
378		if !rw.wroteHeader && rw.statusCode == 0 && caddyhttp.IsIncremental(rw.Header()) {
379			if rw.Header().Get("Content-Type") == "" {
380				rw.Header().Set("Content-Type", http.DetectContentType(p))
381			}
382			rw.WriteHeader(http.StatusOK)
383		}
384	
385		// sniff content-type and determine content-length
386		if !rw.wroteHeader && rw.config.MinLength > 0 {
387			var gtMinLength bool
388			if len(p) > rw.config.MinLength {
389				gtMinLength = true
390			} else if cl, err := strconv.Atoi(rw.Header().Get("Content-Length")); err == nil && cl > rw.config.MinLength {
391				gtMinLength = true
392			}
393	
394			if gtMinLength {
395				if rw.Header().Get("Content-Type") == "" {
396					rw.Header().Set("Content-Type", http.DetectContentType(p))
397				}
398				rw.init()
399			}
400		}
401	
402		// before we write to the response, we need to make
403		// sure the header is written exactly once; we do
404		// that by checking if a status code has been set,
405		// and if so, that means we haven't written the
406		// header OR the default status code will be written
407		// by the standard library
408		if !rw.wroteHeader {
409			if rw.statusCode != 0 {
410				rw.ResponseWriter.WriteHeader(rw.statusCode)
411			}
412			rw.wroteHeader = true
413		}
414	
415		var n int
416		var err error
417		if rw.w != nil {
418			n, err = rw.w.Write(p)
419		} else {
420			n, err = rw.ResponseWriter.Write(p)
421		}
422		if err != nil || !rw.incremental {
423			return n, err
424		}
425		return n, rw.FlushError()
426	}
427	
428	// used to mask ReadFrom method
429	type writerOnly struct {
430		io.Writer
431	}
432	
433	// copied from stdlib
434	const sniffLen = 512
435	
436	// ReadFrom will try to use sendfile to copy from the reader to the response writer.
437	// It's only used if the response writer implements io.ReaderFrom and the data can't be compressed.
438	// It's based on the standard library HTTP/1.1 response writer implementation.
439	// https://github.com/golang/go/blob/f4e3ec3dbe3b8e04a058d266adf8e048bab563f2/src/net/http/server.go#L586
440	func (rw *responseWriter) ReadFrom(r io.Reader) (int64, error) {
441		if rw.incremental || !rw.wroteHeader && caddyhttp.IsIncremental(rw.Header()) {
442			return io.Copy(writerOnly{rw}, r)
443		}
444	
445		rf, ok := rw.ResponseWriter.(io.ReaderFrom)
446		// sendfile can't be used anyway
447		if !ok {
448			// mask ReadFrom to avoid infinite recursion
449			return io.Copy(writerOnly{rw}, r)
450		}
451	
452		var ns int64
453		// try to sniff the content type and determine if the response should be compressed
454		if !rw.wroteHeader && rw.config.MinLength > 0 {
455			var (
456				err error
457				buf [sniffLen]byte
458			)
459			// mask ReadFrom to let Write determine if the response should be compressed
460			ns, err = io.CopyBuffer(writerOnly{rw}, io.LimitReader(r, sniffLen), buf[:])
461			if err != nil || ns < sniffLen {
462				return ns, err
463			}
464		}
465	
466		// the response will be compressed, no sendfile support
467		if rw.w != nil {
468			nr, err := io.Copy(rw.w, r)
469			return nr + ns, err
470		}
471		nr, err := rf.ReadFrom(r)
472		return nr + ns, err
473	}
474	
475	// Close writes any remaining buffered response and
476	// deallocates any active resources.
477	func (rw *responseWriter) Close() error {
478		// didn't write, probably head request
479		if !rw.wroteHeader {
480			cl, err := strconv.Atoi(rw.Header().Get("Content-Length"))
481			if err == nil && cl > rw.config.MinLength {
482				rw.init()
483			}
484	
485			// issue #5059, don't write status code if not set explicitly.
486			if rw.statusCode != 0 {
487				rw.ResponseWriter.WriteHeader(rw.statusCode)
488			}
489			rw.wroteHeader = true
490		}
491	
492		var err error
493		if rw.w != nil {
494			err = rw.w.Close()
495			rw.w.Reset(nil)
496			rw.config.writerPools[rw.encodingName].Put(rw.w)
497			rw.w = nil
498		}
499		return err
500	}
501	
502	// Unwrap returns the underlying ResponseWriter.
503	func (rw *responseWriter) Unwrap() http.ResponseWriter {
504		return rw.ResponseWriter
505	}
506	
507	// init should be called before we write a response, if rw.buf has contents.
508	func (rw *responseWriter) init() {
509		// Don't initialize encoder for responses that must not be encoded.
510		if rw.disabled {
511			return
512		}
513	
514		hdr := rw.Header()
515	
516		if hdr.Get("Content-Encoding") == "" && isEncodeAllowed(hdr) &&
517			rw.config.Match(rw) {
518			rw.w = rw.config.writerPools[rw.encodingName].Get().(Encoder)
519			rw.w.Reset(rw.ResponseWriter)
520			hdr.Del("Content-Length") // https://github.com/golang/go/issues/14975
521			hdr.Set("Content-Encoding", rw.encodingName)
522			if !hasVaryValue(hdr, "Accept-Encoding") {
