1306	// protocol returns true if the protocol proto is configured/enabled.
1307	func (s *Server) protocol(proto string) bool {
1308		if s.ListenProtocols == nil {
1309			return slices.Contains(s.protocolsWithDefaults(), proto)
1310		}
1311	
1312		for _, lnProtocols := range s.ListenProtocols {
1313			if slices.Contains(s.listenerProtocolsWithDefaults(lnProtocols), proto) {
1314				return true
1315			}
1316		}
1317	
1318		return false
1319	}

