426	// GenerateRandomString returns a securely generated random string.
427	// It will return an error if the system's secure random
428	// number generator fails to function correctly, in which
429	// case the caller should not continue.
430	func GenerateRandomString(n int) (string, error) {
431		const letters = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-"
432		bytes, err := GenerateRandomBytes(n)
433		if err != nil {
434			return "", err
435		}
436		for i, b := range bytes {
437			bytes[i] = letters[b%byte(len(letters))]
438		}
439		return string(bytes), nil
