50		var wg sync.WaitGroup
51		var errc = make(chan error, 1)
52		var dst bytes.Buffer
53	
54		copier := switchProtocolCopier{
55			user:       nopReadWriteCloser{Reader: strings.NewReader("hello")},
56			backend:    nopReadWriteCloser{Writer: &dst},
57			wg:         &wg,
58			bufferSize: 7,
59		}
