79	// A clean EOF in one direction must be propagated to the destination as a
80	// write-half close instead of tearing the whole tunnel down.
81	// See https://github.com/caddyserver/caddy/issues/8026.
82	func TestSwitchProtocolCopierHalfClose(t *testing.T) {
83		closeWriteErr := errors.New("no half-close")
84	
85		for _, tc := range []struct {
86			name    string
87			dst     io.ReadWriteCloser
88			wantErr error // nil means the half-close was propagated
89		}{
90			{
91				name:    "destination supports CloseWrite",
92				dst:     &closeWriteRecorder{},
93				wantErr: nil,
94			},
95			{
96				name:    "destination does not support CloseWrite",
97				dst:     nopReadWriteCloser{Writer: io.Discard},
98				wantErr: errCopyDone,
99			},
100			{
101				name:    "CloseWrite fails",
102				dst:     &closeWriteRecorder{err: closeWriteErr},
103				wantErr: closeWriteErr,
104			},
105		} {
106			t.Run(tc.name, func(t *testing.T) {
107				var wg sync.WaitGroup
108				errc := make(chan error, 1)
109				copier := switchProtocolCopier{
110					user:    nopReadWriteCloser{Reader: strings.NewReader("hello")},
111					backend: tc.dst,
112					wg:      &wg,
113				}
114	
115				wg.Add(1)
116				go copier.copyToBackend(errc)
117				wg.Wait()
118	
119				if err := <-errc; !errors.Is(err, tc.wantErr) {
120					t.Fatalf("copyToBackend() error = %v, want %v", err, tc.wantErr)
121				}
122				if rec, ok := tc.dst.(*closeWriteRecorder); ok && !rec.called {
123					t.Fatal("CloseWrite() was not called on a destination that supports it")
124				}
125			})
126		}
127	}
