170	// closeWriteRecorder is a destination that supports closing only its write
171	// half, and records whether that happened.
172	type closeWriteRecorder struct {
173		called   bool
174		err      error
175		writeErr error
176	}
177	
178	func (c *closeWriteRecorder) Read([]byte) (int, error) { return 0, io.EOF }
179	
180	func (c *closeWriteRecorder) Write(p []byte) (int, error) {
181		if c.writeErr != nil {
182			return 0, c.writeErr
183		}
184		return len(p), nil
185	}
186	
187	func (c *closeWriteRecorder) Close() error { return nil }
188	
189	func (c *closeWriteRecorder) CloseWrite() error {
190		c.called = true
191		return c.err
192	}
