194	// TestHandlerUpgradedStreamHalfClose drives a real upgraded stream through the
195	// handler and checks that closing one direction is propagated to the other side
196	// instead of tearing the whole tunnel down.
197	//
198	// It mirrors net/http/httputil's TestReverseProxyWebSocketHalfTCP, which covers
199	// the same class upstream (https://go.dev/issue/35892). Before the fix, the
200	// "close write" cases failed: the handler returned as soon as the first
201	// direction reported, and the deferred closes killed the other direction before
202	// its pending bytes could be delivered.
203	//
204	// See https://github.com/caddyserver/caddy/issues/8026.
205	func TestHandlerUpgradedStreamHalfClose(t *testing.T) {
206		switch runtime.GOOS {
207		case "plan9", "js", "wasip1":
208			t.Skipf("not supported on %s", runtime.GOOS)
209		}
210	
211		// Reads carry a deadline so a regression fails the test promptly instead of
212		// blocking until the whole package times out.
213		const readTimeout = 10 * time.Second
214	
215		mustRead := func(t *testing.T, conn *net.TCPConn, msg string) {
216			t.Helper()
217			if err := conn.SetReadDeadline(time.Now().Add(readTimeout)); err != nil {
218				t.Fatalf("failed to set read deadline: %v", err)
219			}
220			b := make([]byte, len(msg))
221			if _, err := io.ReadFull(conn, b); err != nil {
222				t.Fatalf("failed to read: %v", err)
223			}
224			if got, want := string(b), msg; got != want {
225				t.Fatalf("got %#q, want %#q", got, want)
226			}
227		}
228	
229		mustReadEOF := func(t *testing.T, conn *net.TCPConn) {
230			t.Helper()
231			if err := conn.SetReadDeadline(time.Now().Add(readTimeout)); err != nil {
232				t.Fatalf("failed to set read deadline: %v", err)
233			}
234			b := make([]byte, 1)
235			if _, err := conn.Read(b); !errors.Is(err, io.EOF) {
236				t.Fatalf("read after peer half-close: got %v, want EOF", err)
237			}
238		}
239	
240		mustWrite := func(t *testing.T, conn *net.TCPConn, msg string) {
241			t.Helper()
242			if _, err := conn.Write([]byte(msg)); err != nil {
243				t.Fatalf("failed to write: %v", err)
244			}
245		}
246	
247		mustCloseRead := func(t *testing.T, conn *net.TCPConn) {
248			t.Helper()
249			if err := conn.CloseRead(); err != nil {
250				t.Fatalf("failed to CloseRead: %v", err)
251			}
252		}
253	
254		mustCloseWrite := func(t *testing.T, conn *net.TCPConn) {
255			t.Helper()
256			if err := conn.CloseWrite(); err != nil {
257				t.Fatalf("failed to CloseWrite: %v", err)
258			}
259		}
260	
261		tests := map[string]func(t *testing.T, cli, srv *net.TCPConn){
262			"backend close read": func(t *testing.T, cli, srv *net.TCPConn) {
263				mustCloseRead(t, srv)
264				mustWrite(t, srv, "backend sends")
265				mustRead(t, cli, "backend sends")
266			},
267			"backend close write": func(t *testing.T, cli, srv *net.TCPConn) {
268				mustCloseWrite(t, srv)
269				mustReadEOF(t, cli)
270				mustWrite(t, cli, "client sends")
271				mustRead(t, srv, "client sends")
272			},
273			"client close read": func(t *testing.T, cli, srv *net.TCPConn) {
274				mustCloseRead(t, cli)
275				mustWrite(t, cli, "client sends")
276				mustRead(t, srv, "client sends")
277			},
278			"client close write": func(t *testing.T, cli, srv *net.TCPConn) {
279				mustCloseWrite(t, cli)
280				mustReadEOF(t, srv)
281				mustWrite(t, srv, "backend sends")
282				mustRead(t, cli, "backend sends")
283			},
284		}
285	
286		for name, test := range tests {
287			t.Run(name, func(t *testing.T) {
288				srvc := make(chan *net.TCPConn, 1)
289	
290				backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
291					conn, _, err := http.NewResponseController(w).Hijack()
292					if err != nil {
293						t.Errorf("backend hijack failed: %v", err)
294						return
295					}
296					tcp, ok := conn.(*net.TCPConn)
297					if !ok {
298						conn.Close()
299						t.Errorf("backend conn is %T, want *net.TCPConn", conn)
300						return
301					}
302					if _, err := io.WriteString(tcp, "HTTP/1.1 101 Switching Protocols\r\nConnection: Upgrade\r\nUpgrade: websocket\r\n\r\n"); err != nil {
303						tcp.Close()
304						t.Errorf("backend upgrade write failed: %v", err)
305						return
306					}
307					srvc <- tcp
308				}))
309				defer backend.Close()
310	
311				h := minimalHandler(0, &Upstream{
312					Host: new(Host),
313					Dial: backend.Listener.Addr().String(),
314				})
315				h.connections = make(map[io.ReadWriteCloser]openConnection)
316				h.connectionsMu = new(sync.Mutex)
317	
318				frontend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
319					// Isolate half-close propagation from request cancellation which has
320					// its own backend-close path.
321					r = r.WithContext(context.WithoutCancel(r.Context()))
322					_ = h.ServeHTTP(w, prepareTestRequest(r), caddyhttp.HandlerFunc(func(http.ResponseWriter, *http.Request) error {
323						return nil
324					}))
325				}))
326				defer frontend.Close()
327	
328				frontendURL, err := url.Parse(frontend.URL)
329				if err != nil {
330					t.Fatalf("failed to parse frontend URL: %v", err)
331				}
332				addr, err := net.ResolveTCPAddr("tcp", frontendURL.Host)
333				if err != nil {
334					t.Fatalf("failed to resolve TCP address: %v", err)
335				}
336				cli, err := net.DialTCP("tcp", nil, addr)
337				if err != nil {
338					t.Fatalf("failed to dial frontend: %v", err)
339				}
340				defer cli.Close()
341	
342				req, _ := http.NewRequest(http.MethodGet, frontend.URL, nil)
343				req.Header.Set("Connection", "Upgrade")
344				req.Header.Set("Upgrade", "websocket")
345				if err := req.Write(cli); err != nil {
346					t.Fatalf("failed to write upgrade request: %v", err)
347				}
348	
349				resp, err := http.ReadResponse(bufio.NewReader(cli), &http.Request{Method: http.MethodGet})
350				if err != nil {
351					t.Fatalf("failed to read upgrade response: %v", err)
352				}
353				if resp.StatusCode != http.StatusSwitchingProtocols {
354					t.Fatalf("status = %d, want 101", resp.StatusCode)
355				}
356	
357				var srv *net.TCPConn
358				select {
359				case srv = <-srvc:
360				case <-time.After(5 * time.Second):
361					t.Fatal("timed out waiting for the backend connection")
362				}
363				defer srv.Close()
364	
365				test(t, cli, srv)
366			})
367		}
368	}
