func (r *streamRegistry) add(s *upgradedStream) (remove func()) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.streams[s.upstream] == nil {
		r.streams[s.upstream] = make(map[*upgradedStream]struct{})
	}
	r.streams[s.upstream][s] = struct{}{}
	return func() {
