		{logs: &StreamLogs{}},
		{logs: &StreamLogs{SkipHandshake: true}, wantSkip: true},
		{logs: &StreamLogs{Level: "info"}},
		{logs: &StreamLogs{Level: "bogus"}, wantErr: true},
	} {
