	detachedStreams.mu.Lock()
	defer detachedStreams.mu.Unlock()
	return len(detachedStreams.streams[p.upstream])
}

func (p *upgradeProxy) request() *http.Request {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.req
}

