	if rest := p.expectClosed(); !bytes.Equal(rest, []byte{0x88, 0x02, 0x03, 0xe9}) {
		t.Errorf("received %x when the stream was closed, want a close frame", rest)
	}
	p.waitForClosed(streamResultUpstreamRemoved)
}

